pub fn CARDCheckAsync<'a>(ctx: &'a Ctx, chan: i32, callback: FnPtr<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x18);
    let xferBytes: Val<'a, i32> = frame_at(ctx, &__frame, 0x8);
    let mut chan = chan;
    let mut callback = callback;
    return fns::CARDCheckExAsync(ctx, chan, xferBytes, callback);
}

fn inl___CARDCheckSum_unfused<'a>(
    ctx: &'a Ctx,
    ptr_: Addr<'a>,
    length: i32,
    checksum: Val<'a, u16>,
    checksumInv: Val<'a, u16>,
) {
    let mut ptr_ = ptr_;
    let mut length = length;
    let mut checksum = checksum;
    let mut checksumInv = checksumInv;
    let mut p: Val<'a, u16> = null(ctx);
    let mut i: i32 = 0;
    length = div_i32(length, (2_u32 as i32));
    (checksum).set({
        let __t1 = (0_i32 as u16);
        (checksumInv).set(__t1);
        __t1
    });
    {
        i = 0_i32;
        p = Handle::cast::<Val<'a, u16>>(ptr_);
        'l1: while i < length {
            'c2: {
                (checksum).set((((checksum).get() as i32).wrapping_add(((p).get() as i32)) as u16));
                (checksumInv)
                    .set((((checksumInv).get() as i32).wrapping_add((!((p).get() as i32))) as u16));
            }
            i = i.wrapping_add(1);
            p = Handle::add(p, 1);
        }
    }
    if ((checksum).get() as i32) == 0xffff_i32 {
        (checksum).set((0_i32 as u16));
    }
    if ((checksumInv).get() as i32) == 0xffff_i32 {
        (checksumInv).set((0_i32 as u16));
    }
}

